// Package chain wraps the Ethereum JSON-RPC client and the contract ABIs heimdalld needs.
package chain

import (
	"embed"
	"encoding/json"
	"fmt"
	"strings"

	"github.com/ethereum/go-ethereum/accounts/abi"
	"github.com/ethereum/go-ethereum/common/hexutil"
)

// Heimdall ABIs are generated by scripts/gen-abi.sh from Foundry output; never hand-edit.
//
//go:embed abi/HeimdallGuard.json abi/HeimdallGuardFactory.json abi/MockLendingVault.json abi/MockPriceFeed.json
var abiFS embed.FS

func mustParse(js string) abi.ABI {
	a, err := abi.JSON(strings.NewReader(js))
	if err != nil {
		panic(fmt.Sprintf("bad ABI: %v", err))
	}
	return a
}

func embedded(name string) []byte {
	b, err := abiFS.ReadFile("abi/" + name)
	if err != nil {
		panic(err)
	}
	return b
}

var (
	GuardABI        = mustParse(string(embedded("HeimdallGuard.json")))
	FactoryABI      = mustParse(string(embedded("HeimdallGuardFactory.json")))
	MockVaultABI    = mustParse(string(embedded("MockLendingVault.json")))
	MockFeedABI     abi.ABI
	MockFeedRuntime []byte // deployed bytecode of MockPriceFeed (simulator only)
)

func init() {
	var f struct {
		ABI      json.RawMessage `json:"abi"`
		Deployed string          `json:"deployedBytecode"`
	}
	if err := json.Unmarshal(embedded("MockPriceFeed.json"), &f); err != nil {
		panic(err)
	}
	MockFeedABI = mustParse(string(f.ABI))
	b, err := hexutil.Decode(f.Deployed)
	if err != nil {
		panic(err)
	}
	MockFeedRuntime = b
}

