// getReserveData returns a fully static struct (15 words, layout in IAavePool.sol). The output is
// declared as bytes only so the fragment parses; AaveReserve decodes the raw return data word by word.
const aavePoolJSON = `[
 {"type":"function","name":"supply","stateMutability":"nonpayable","inputs":[{"name":"asset","type":"address"},{"name":"amount","type":"uint256"},{"name":"onBehalfOf","type":"address"},{"name":"referralCode","type":"uint16"}],"outputs":[]},
 {"type":"function","name":"getReserveData","stateMutability":"view","inputs":[{"name":"asset","type":"address"}],"outputs":[{"name":"","type":"bytes"}]}
]`

var (
	ERC20ABI      = mustParse(erc20JSON)
	ERC4626ABI    = mustParse(erc4626JSON)
	AggregatorABI = mustParse(aggregatorJSON)
	AavePoolABI   = mustParse(aavePoolJSON)
)

